type individual = {
  establishes_closer_connection_to_foreign_country : bool; (* 7701(b)(2)(C)(i) claim *)
  days_present_with_closer_connection : int; (* days individual claims the closer-connection exception for *)
}

let max_disregarded_days = 10 (* 7701(b)(2)(C)(ii) cap *)

(* number of days of US presence disregarded under 7701(b)(2)(C) *)
let days_of_presence_disregarded (individual : individual) : int =
  if individual.establishes_closer_connection_to_foreign_country then
    min individual.days_present_with_closer_connection max_disregarded_days
  else 0
